payload.script:
WinHUB Backup Report: {{ job_title }}
Generated by WinHUB

{% for result in results %}
Host: {{ result.host }}
Status: {{ result.status }}
{% if result.data %}
Project: {{ result.data.project }}
Task: {{ result.data.task }}
Target server: {{ result.data.target_server }}
Destination: {{ result.data.backup_destination }}
Started: {{ result.data.started_at }}
Finished: {{ result.data.finished_at }}
Duration seconds: {{ result.data.duration_seconds }}

Recursive folders:
{% for item in result.data.recursive_folders %}- {{ item }}
{% endfor %}
Single folders:
{% for item in result.data.single_folders %}- {{ item }}
{% endfor %}
Created archives:
{% for item in result.data.archives %}- {{ item.name }} ({{ item.size_mb }} MB)
{% endfor %}
Warnings:
{% for item in result.data.warnings %}- {{ item }}
{% else %}- none
{% endfor %}
{% if result.data.error %}
Error: {{ result.data.error }}
{% endif %}
{% else %}
{{ result.log }}
{% endif %}
---
{% endfor %}

$ErrorActionPreference = 'Stop'
[Console]::InputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

$StartedAt = Get-Date
$Warnings = New-Object System.Collections.Generic.List[string]
$Session = $null

function Split-WinHubList {
    param([string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return @() }
    return @($Value -split "[`r`n,;]+" | ForEach-Object { $_.Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
}

function Unprotect-SyneSecret {
    param([string]$EncryptedBase64, [string]$MasterPassword)
    [byte[]]$Salt = [System.Text.Encoding]::ASCII.GetBytes("Boombdrfg45454vvbSalt_20282")
    try {
        $AllBytes = [Convert]::FromBase64String($EncryptedBase64)
        if ($AllBytes.Length -lt 16) { return $null }
        $IV = $AllBytes[0..15]
        $CipherBytes = $AllBytes[16..($AllBytes.Length - 1)]
        $Rfc = New-Object System.Security.Cryptography.Rfc2898DeriveBytes($MasterPassword, $Salt, 100000, [System.Security.Cryptography.HashAlgorithmName]::SHA256)
        $Key = $Rfc.GetBytes(32)
        $Aes = New-Object System.Security.Cryptography.RijndaelManaged
        $Aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $Aes.Padding = [System.Security.Cryptography.PaddingMode]::PKCS7
        $Aes.KeySize = 256
        $Aes.BlockSize = 128
        $Aes.Key = $Key
        $Aes.IV = $IV
        $Decryptor = $Aes.CreateDecryptor()
        $MemStream = New-Object System.IO.MemoryStream($CipherBytes, $false)
        $CryptoStream = New-Object System.Security.Cryptography.CryptoStream($MemStream, $Decryptor, [System.Security.Cryptography.CryptoStreamMode]::Read)
        $Reader = New-Object System.IO.StreamReader($CryptoStream)
        $Result = $Reader.ReadToEnd()
        $Reader.Close(); $CryptoStream.Close(); $MemStream.Close()
        return $Result
    } catch { return $null }
}

function Get-WinHubCredential {
    param([string]$Target, [string]$Purpose)
    $cred = Get-StoredCredential -Target $Target
    if (-not $cred) { throw "Credential '$Target' for $Purpose was not found in Windows Credential Manager." }
    return $cred
}

try {
    if (-not (Get-Command Get-StoredCredential -ErrorAction SilentlyContinue)) {
        try { Import-Module CredentialManager -ErrorAction Stop }
        catch { throw "PowerShell module CredentialManager is not installed." }
    }

    $ProjectName = "{{project_name}}"
    $TaskName = "{{task_name}}"
    $TargetServer = "{{target_server}}"
    $BackupDestination = "{{backup_destination}}"
    $MasterCredName = "{{master_cred_name}}"
    $NasCredTarget = "{{nas_cred_target}}"
    $ArchiveCredTarget = "{{archive_cred_target}}"
    $WinRARPath = "{{winrar_path}}"
    $TempDir = "{{temp_dir}}"
    $ShadowDrive = "{{shadow_drive}}"
    $RecursiveFolders = Split-WinHubList "{{recursive_folders}}"
    $SingleFolders = Split-WinHubList "{{single_folders}}"

    if ([string]::IsNullOrWhiteSpace($ProjectName)) { $ProjectName = "Backup" }
    if ([string]::IsNullOrWhiteSpace($TaskName)) { $TaskName = $TargetServer }
    if ([string]::IsNullOrWhiteSpace($WinRARPath)) { $WinRARPath = "C:\Program Files\WinRAR\WinRAR.exe" }
    if ([string]::IsNullOrWhiteSpace($TempDir)) { $TempDir = "C:\Temp_Backup" }
    if ([string]::IsNullOrWhiteSpace($ShadowDrive)) { $ShadowDrive = "S:" }
    if ([string]::IsNullOrWhiteSpace($BackupDestination)) { throw "Backup destination is empty." }
    if ([string]::IsNullOrWhiteSpace($TargetServer)) { throw "Target server is empty." }
    if (($RecursiveFolders.Count + $SingleFolders.Count) -eq 0) { throw "No source folders were provided." }

    $ArchiveCredObj = Get-WinHubCredential -Target $ArchiveCredTarget -Purpose "RAR password"
    $ArchivePass = $ArchiveCredObj.GetNetworkCredential().Password
    $NasCredObj = Get-WinHubCredential -Target $NasCredTarget -Purpose "NAS access"
    $ShareUser = $NasCredObj.UserName
    $SharePass = $NasCredObj.GetNetworkCredential().Password
    $MasterCredObj = Get-WinHubCredential -Target $MasterCredName -Purpose "server password master key"
    $MasterKey = $MasterCredObj.GetNetworkCredential().Password
    $TargetCredObj = Get-WinHubCredential -Target $TargetServer -Purpose "target server access"
    $TargetUser = $TargetCredObj.UserName
    $EncBlob = $TargetCredObj.GetNetworkCredential().Password
    $PlainPass = Unprotect-SyneSecret -EncryptedBase64 $EncBlob -MasterPassword $MasterKey
    if (-not $PlainPass) { $PlainPass = $EncBlob }

    $SecPass = ConvertTo-SecureString $PlainPass -AsPlainText -Force
    $AdminCred = New-Object System.Management.Automation.PSCredential($TargetUser, $SecPass)
    $SessionOption = New-PSSessionOption -SkipCACheck -SkipCNCheck
    $Session = New-PSSession -ComputerName $TargetServer -UseSSL -Port 5986 -Credential $AdminCred -SessionOption $SessionOption -ErrorAction Stop

    $RemoteResult = Invoke-Command -Session $Session -ScriptBlock {
        param($RecursiveFolders, $SingleFolders, $WinRARPath, $ArchivePass, $DestPath, $NetUser, $NetPass, $TempDir, $ShadowDrive)
        $RemoteWarnings = New-Object System.Collections.Generic.List[string]
        $ScriptFile = Join-Path $TempDir 'diskshadow.dsh'
        $MetaFile = Join-Path $TempDir 'vss_metadata.cab'
        $MappedDriveLetter = "Z"
        $MappedDrivePath = "$MappedDriveLetter`:"
        $Archives = @()

        if (Test-Path $TempDir) { Remove-Item $TempDir -Recurse -Force -ErrorAction SilentlyContinue }
        New-Item -ItemType Directory -Path $TempDir | Out-Null
        if (-not (Test-Path $WinRARPath)) { throw "WinRAR was not found at '$WinRARPath'." }

        $AllFolders = @($RecursiveFolders + $SingleFolders)
        $FirstExisting = $AllFolders | Where-Object { Test-Path $_ } | Select-Object -First 1
        if (-not $FirstExisting) { throw "None of the source folders exists on the target server." }
        $SourceVolume = Split-Path $FirstExisting -Qualifier

        foreach ($Folder in $AllFolders) {
            if (-not (Test-Path $Folder)) { $RemoteWarnings.Add("Source folder does not exist: $Folder"); continue }
            $FolderVolume = Split-Path $Folder -Qualifier
            if ($FolderVolume -ne $SourceVolume) { $RemoteWarnings.Add("Skipped $Folder because it is on $FolderVolume; this task snapshots only $SourceVolume.") }
        }

        $PreCleanup = "delete shadows exposed $ShadowDrive"
        $PreCleanup | Out-File -FilePath "$ScriptFile.clean" -Encoding ASCII
        cmd /c "diskshadow /s `"$ScriptFile.clean`"" | Out-Null

        $DshContent = @"
set context persistent
set verbose on
set metadata $MetaFile
add volume $SourceVolume alias BackupVol
create
expose %BackupVol% $ShadowDrive
"@
        $DshContent | Out-File -FilePath $ScriptFile -Encoding ASCII

        try {
            $VssResult = cmd /c "diskshadow /s `"$ScriptFile`"" 2>&1
            if (-not (Test-Path $ShadowDrive)) { throw "VSS snapshot was not created. Diskshadow output: $($VssResult | Out-String)" }
            function Get-ShadowPath([string]$Path) { return $Path -replace ("^" + [regex]::Escape($SourceVolume)), $ShadowDrive }

            foreach ($Folder in $RecursiveFolders) {
                if (-not (Test-Path $Folder)) { continue }
                if ((Split-Path $Folder -Qualifier) -ne $SourceVolume) { continue }
                $Name = Split-Path $Folder -Leaf
                $ArchiveName = "$Name" + "_rec_$(Get-Date -Format 'yyyyMMdd_HHmm').rar"
                $FullArchiveName = Join-Path $TempDir $ArchiveName
                $ShadowSource = Get-ShadowPath $Folder
                $args = "a -r -ep1 -m5 -hp$ArchivePass `"$FullArchiveName`" `"$ShadowSource`""
                $proc = Start-Process -FilePath $WinRARPath -ArgumentList $args -NoNewWindow -Wait -PassThru
                if ($proc.ExitCode -ne 0) { throw "WinRAR failed for $Folder with exit code $($proc.ExitCode)." }
                $Archives += $ArchiveName
            }

            foreach ($Folder in $SingleFolders) {
                if (-not (Test-Path $Folder)) { continue }
                if ((Split-Path $Folder -Qualifier) -ne $SourceVolume) { continue }
                $Name = Split-Path $Folder -Leaf
                $ArchiveName = "$Name" + "_sngl_$(Get-Date -Format 'yyyyMMdd_HHmm').rar"
                $FullArchiveName = Join-Path $TempDir $ArchiveName
                $ShadowSource = Get-ShadowPath $Folder
                $args = "a -ep1 -m5 -hp$ArchivePass `"$FullArchiveName`" `"$ShadowSource`""
                $proc = Start-Process -FilePath $WinRARPath -ArgumentList $args -NoNewWindow -Wait -PassThru
                if ($proc.ExitCode -ne 0) { throw "WinRAR failed for $Folder with exit code $($proc.ExitCode)." }
                $Archives += $ArchiveName
            }

            if ($Archives.Count -eq 0) { throw "No archives were created." }
            if (Get-PSDrive -Name $MappedDriveLetter -ErrorAction SilentlyContinue) { Remove-PSDrive -Name $MappedDriveLetter -Force -ErrorAction SilentlyContinue }
            cmd /c "net use $MappedDrivePath /delete /y 2>nul" | Out-Null
            if (-not [string]::IsNullOrWhiteSpace($NetUser)) {
                $SecNetPass = ConvertTo-SecureString $NetPass -AsPlainText -Force
                $NetCred = New-Object System.Management.Automation.PSCredential($NetUser, $SecNetPass)
                New-PSDrive -Name $MappedDriveLetter -PSProvider FileSystem -Root $DestPath -Credential $NetCred | Out-Null
            } else {
                New-PSDrive -Name $MappedDriveLetter -PSProvider FileSystem -Root $DestPath | Out-Null
            }
            if (-not (Test-Path $MappedDrivePath)) { throw "Network destination could not be mounted." }

            $ArchiveResults = @()
            foreach ($Archive in $Archives) {
                $SourceFile = Join-Path $TempDir $Archive
                Copy-Item -Path $SourceFile -Destination $MappedDrivePath -Force
                $Item = Get-Item $SourceFile
                $ArchiveResults += [pscustomobject]@{ name = $Archive; size_mb = [math]::Round($Item.Length / 1MB, 2) }
            }
            [pscustomobject]@{ archives = $ArchiveResults; warnings = @($RemoteWarnings) }
        } finally {
            Remove-PSDrive -Name $MappedDriveLetter -Force -ErrorAction SilentlyContinue
            cmd /c "net use $MappedDrivePath /delete /y 2>nul" | Out-Null
            $CleanupScript = "delete shadows exposed $ShadowDrive"
            $CleanupScript | Out-File -FilePath "$ScriptFile.clean" -Encoding ASCII
            cmd /c "diskshadow /s `"$ScriptFile.clean`"" | Out-Null
            Remove-Item $TempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
    } -ArgumentList $RecursiveFolders, $SingleFolders, $WinRARPath, $ArchivePass, $BackupDestination, $ShareUser, $SharePass, $TempDir, $ShadowDrive

    foreach ($item in @($RemoteResult.warnings)) { if ($item) { $Warnings.Add([string]$item) } }
    $FinishedAt = Get-Date
    $Result = [ordered]@{
        winhub_report_type = "universal_vss_backup"
        project = $ProjectName
        task = $TaskName
        target_server = $TargetServer
        backup_destination = $BackupDestination
        recursive_folders = @($RecursiveFolders)
        single_folders = @($SingleFolders)
        archives = @($RemoteResult.archives)
        warnings = @($Warnings)
        started_at = $StartedAt.ToString("yyyy-MM-dd HH:mm:ss")
        finished_at = $FinishedAt.ToString("yyyy-MM-dd HH:mm:ss")
        duration_seconds = [int]($FinishedAt - $StartedAt).TotalSeconds
    }
    $Result | ConvertTo-Json -Depth 8 -Compress
} catch {
    $FinishedAt = Get-Date
    $Result = [ordered]@{
        winhub_report_type = "universal_vss_backup"
        project = "{{project_name}}"
        task = "{{task_name}}"
        target_server = "{{target_server}}"
        backup_destination = "{{backup_destination}}"
        recursive_folders = @(Split-WinHubList "{{recursive_folders}}")
        single_folders = @(Split-WinHubList "{{single_folders}}")
        archives = @()
        warnings = @($Warnings)
        started_at = $StartedAt.ToString("yyyy-MM-dd HH:mm:ss")
        finished_at = $FinishedAt.ToString("yyyy-MM-dd HH:mm:ss")
        duration_seconds = [int]($FinishedAt - $StartedAt).TotalSeconds
        error = $_.Exception.Message
    }
    $Result | ConvertTo-Json -Depth 8 -Compress
    exit 1
} finally {
    if ($Session) { Remove-PSSession $Session -ErrorAction SilentlyContinue }
    $MasterKey = $null; $PlainPass = $null; $ArchivePass = $null; $SharePass = $null
    [System.GC]::Collect()
}
